FuncDef.Code:
vec3 backdropSimpleHorizon(
    in vec3 dir,
    in vec3 colorTop,
    in vec3 colorMiddle,
    in vec3 colorBottom,
    in float contrastMul,
    in float contrastPow
)
{
    float t = 0.5 * dir.y + 0.5; // [-1,1] -> [0,1]

    vec3 bottomToMid = mix(colorBottom, colorMiddle, t * 2.0);
    vec3 midToTop    = mix(colorMiddle, colorTop, (t - 0.5) * 2.0);

    vec3 color = mix(bottomToMid, midToTop, step(0.5, t));

    // contrast
    color *= contrastMul;
    color = pow(color, vec3(contrastPow));
    color = clamp(color, 0.0, 1.0);

    return color;
}
